def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    my_last, op_last = history[-1]

    my_d = 0
    op_d = 0
    for a, b in history:
        if a == 'D':
            my_d += 1
        if b == 'D':
            op_d += 1

    k = min(n, 10)
    recent = history[-k:]
    my_recent_d = 0
    opp_recent_d = 0
    for a, b in recent:
        if a == 'D':
            my_recent_d += 1
        if b == 'D':
            opp_recent_d += 1

    retal = 0
    forg = 0
    unprov = 0
    for i in range(n - 1):
        m_i = history[i][0]
        o_next = history[i + 1][1]
        if m_i == 'D':
            if o_next == 'D':
                retal += 1
            else:
                forg += 1
        elif o_next == 'D':
            unprov += 1

    exp_streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'C':
            exp_streak += 1
        else:
            break

    if n == 20 and op_last == 'C' and my_d == 0 and op_d <= 2:
        return 'D'

    if op_last == 'C' and forg >= 1 and retal == 0:
        pure_nice = op_d == 0 and unprov == 0
        threshold_ok = op_d <= max(3, n // 10) and unprov <= max(1, n // 10)
        if pure_nice and n >= 30:
            if exp_streak > 0 or n >= 70:
                return 'D'
            if n <= 97 and rng.random() < 0.25:
                return 'D'
        elif not pure_nice and n >= 50 and threshold_ok:
            if exp_streak > 0:
                return 'D'
            if n <= 97 and rng.random() < 0.25:
                return 'D'

    if op_last == 'D':
        if op_d == n or op_d >= max(4, n - 2):
            return 'D'
        if op_d >= max(5, n // 2) or opp_recent_d >= 7:
            return 'D'
        if op_d <= max(3, n // 8) and opp_recent_d <= 2 and unprov == 0:
            return 'C'
        if my_last == 'D' and op_d * 2 <= n and opp_recent_d <= 4 and unprov <= 1:
            return 'C'
        return 'D'

    if op_d >= max(6, n // 2) or opp_recent_d >= 6:
        return 'D'
    return 'C'
